input.command:
cd mobil && URL=$(grep '^EXPO_PUBLIC_SUPABASE_URL=' .env | cut -d= -f2- | tr -d '') && SK=$(grep '^SUPABASE_SERVICE_ROLE_KEY=' .env | cut -d= -f2- | tr -d '') && PK=$(grep '^EXPO_PUBLIC_SUPABASE_ANON_KEY=' .env | cut -d= -f2- | tr -d '') && echo "=== gizli anahtarla istek_gunlugu okumasi (RLS politikasi YOK, yalnizca yonetici gecebilir) ===" && curl -s -o /dev/null -w "HTTP %{http_code}
" "$URL/rest/v1/istek_gunlugu?select=id&limit=1" -H "apikey: $SK" -H "Authorization: Bearer $SK" && echo "=== ayni istek, ACIK anahtarla (gecmemeli ya da bos donmeli) ===" && curl -s -w "
HTTP %{http_code}
" "$URL/rest/v1/istek_gunlugu?select=id&limit=1" -H "apikey: $PK" -H "Authorization: Bearer $PK" | tail -3

URL=$(grep '^EXPO_PUBLIC_SUPABASE_URL=' .env | cut -d= -f2- | tr -d '') && SK=$(grep '^SUPABASE_SERVICE_ROLE_KEY=' .env | cut -d= -f2- | tr -d '') && PK=$(grep '^EXPO_PUBLIC_SUPABASE_ANON_KEY=' .env | cut -d= -f2- | tr -d '') && echo "=== ACIK anahtarla konusmalar silme (reddedilmeli) ===" && curl -s -w "
HTTP %{http_code}
" -X DELETE "$URL/rest/v1/konusmalar?tur=eq.asla_olmayan" -H "apikey: $PK" -H "Authorization: Bearer $PK" | tail -2 && echo "=== GIZLI anahtarla ayni silme (gecmeli) ===" && curl -s -w "
HTTP %{http_code}
" -X DELETE "$URL/rest/v1/konusmalar?tur=eq.asla_olmayan" -H "apikey: $SK" -H "Authorization: Bearer $SK" | tail -2

URL=$(grep '^EXPO_PUBLIC_SUPABASE_URL=' .env | cut -d= -f2- | tr -d '') && SK=$(grep '^SUPABASE_SERVICE_ROLE_KEY=' .env | cut -d= -f2- | tr -d '') && PK=$(grep '^EXPO_PUBLIC_SUPABASE_ANON_KEY=' .env | cut -d= -f2- | tr -d '') && echo "=== ACIK anahtarla konusmalar'a ekleme (REDDEDILMELI) ===" && curl -s -w "
HTTP %{http_code}
" -X POST "$URL/rest/v1/konusmalar" -H "apikey: $PK" -H "Authorization: Bearer $PK" -H "Content-Type: application/json" -d '{"tur":"birebir"}' | tail -2 && echo "=== GIZLI anahtarla ayni ekleme (GECMELI) ===" && curl -s -w "
HTTP %{http_code}
" -X POST "$URL/rest/v1/konusmalar" -H "apikey: $SK" -H "Authorization: Bearer $SK" -H "Content-Type: application/json" -H "Prefer: return=representation" -d '{"tur":"birebir"}' | tail -2

input.query:
delete from public.konusmalar;
select (select count(*) from public.konusmalar) as konusmalar,
       (select count(*) from public.mesajlar) as mesajlar,
       (select count(*) from public.istek_gunlugu) as kota;
